from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, write_time]
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # check if key exists and expired
            if key in cache:
                wtime = cache[key][1]
                if t >= wtime + ttl:
                    # expired, remove it (treat as absent)
                    del cache[key]

            if key in cache:
                # update existing, not expired
                cache[key][0] = value
                cache[key][1] = t
                cache.move_to_end(key)
            else:
                # new entry (or was expired and removed)
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = [value, t]
                cache.move_to_end(key)

        elif op[0] == 'get':
            _, t, key = op
            if key in cache:
                wtime = cache[key][1]
                if t >= wtime + ttl:
                    # expired
                    del cache[key]
                    results.append(-1)
                else:
                    value = cache[key][0]
                    cache.move_to_end(key)
                    results.append(value)
            else:
                results.append(-1)

    return results

